# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""arccosh / arccosh_out 的 GCU400 专属实现（1D flat kernel，out-of-place）。

P19 修复：KernelGen 原版按 cdiv(n, 1024) 一 CTA 一块排布，core shape
(536870912,) 需要 524288 个 CTA，超过 GCU400 grid.x 硬上限 65535
（OutOfResources）。改为 48 CTA 常驻 + tile 循环，任意规模都不越限。

性能（沿用 arccosh_.py 已实测的同款形态，512M 元素 do_bench）：
sqrt 在 GCU400 是软件向量调用、rsqrt 是硬件原语，故
    sqrt(q) = q * rsqrt(max(q, 1e-30)),  q = x*x - 1
把软件 sqrt 全部消掉；N % BLOCK == 0 时走 EVEN 特化去掉 mask；
tile 分档：N<=32768 取 next_pow2(N)（下限 1024）/nw4，N<4M 取 8192/nw4，
fp32 在 4M~32M 取 32768/nw4/网格跨步（16.7M 实测 53.3us，优于 B65536+SLAB
的 59.3us），再大取 65536/nw4/连续分段（SLAB，摊平 HBM 通道热点）；
16-bit 取 65536/nw2/网格跨步。16-bit 大档归因：纯 cvt 往返（load→fp32→
store）可打满 3.2 TB/s，说明 cvt/访存均非瓶颈，1.25 TB/s 的墙在数学链
（log 软件序列）的 ALU 吞吐，log2/fma 变体实测均无收益。

边界语义与 torch.arccosh 对齐：x==1 → q=0 ⇒ ln(1)=0；|x|<1 → q<0，
q*rsqrt(1e-30) 为极大负值 ⇒ ln(负数)=NaN；x=+inf → inf（乘子 clamp 到
f32 max，见 kernel 注释）；x=-inf/NaN → NaN。
整型输入按 INT_TO_FLOAT 提升为默认浮点 dtype（kernel 内 fp32 计算后按
out 指针类型隐式落盘）。
"""

import logging
from contextlib import nullcontext  # noqa: F401

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.utils import libentry

logger = logging.getLogger(__name__)

# GCU400: 4 DIE × 6 SIP, resident CTA count aligned with the topology
NUM_SIPS = 24
MAX_GRID = NUM_SIPS * 2
BLOCK_LARGE = 65536
BLOCK_MID = 8192


@libentry()
@triton.jit
def arccosh_kernel(
    x_ptr, out_ptr, N, BLOCK: tl.constexpr, EVEN: tl.constexpr, SLAB: tl.constexpr
):
    pid = tl.program_id(0)
    num_pids = tl.num_programs(0)
    num_blocks = (N + BLOCK - 1) // BLOCK
    if SLAB:
        per_pid = (num_blocks + num_pids - 1) // num_pids
        begin = pid * per_pid
        end = tl.minimum(begin + per_pid, num_blocks)
        step = 1
    else:
        begin = pid
        end = num_blocks
        step = num_pids
    for block_id in tl.range(begin, end, step):
        off = block_id * BLOCK + tl.arange(0, BLOCK)
        if EVEN:
            x = tl.load(x_ptr + off).to(tl.float32)
        else:
            mask = off < N
            x = tl.load(x_ptr + off, mask=mask).to(tl.float32)
        # sqrt(x^2-1) = (x^2-1) * rsqrt(max(x^2-1, 1e-30)): eliminates the software sqrt.
        # Clamp the multiplier further to f32 max: at x=±inf, q=inf and rsqrt(inf)=0, so multiplying directly gives
        # inf*0=NaN; after clamping, f32max*0=0 and log(±inf+0)=inf/NaN, matching torch.
        # Finite q (including negative values) is unaffected by the clamp.
        q = x * x - 1.0
        y = tl.log(
            x + tl.minimum(q, 3.4028234663852886e38) * tl.rsqrt(tl.maximum(q, 1e-30))
        )
        if EVEN:
            tl.store(out_ptr + off, y)
        else:
            tl.store(out_ptr + off, y, mask=mask)


def _choose_config(num_elements, dtype):
    """返回 (BLOCK, num_warps, slab)：按元素个数与 dtype 选 tile，见模块 docstring。"""
    if num_elements <= 32768:
        return max(1024, triton.next_power_of_2(num_elements)), 4, False
    if num_elements < 1 << 22:
        return BLOCK_MID, 4, False
    # fp32 uses 4 warps + contiguous segmentation (contiguous segmentation evens out HBM channel hot spots on a 2GB
    # buffer);
    # 16-bit halves the traffic, so 2 warps + grid-stride is better (same conclusion measured in arccosh_.py).
    if dtype == torch.float32:
        # Mid range of 4M~32M: B32768 + grid-stride beats B65536 + SLAB (at 16.7M measured
        # 53.3us vs 59.3us; with few waves segmentation cannot amortize); above that, fall back to B65536 + SLAB.
        if num_elements < 1 << 25:
            return 32768, 4, False
        return BLOCK_LARGE, 4, True
    return BLOCK_LARGE, 2, False


def _launch(x, out):
    num_elements = x.numel()
    if num_elements == 0:
        return out
    block_size, num_warps, slab = _choose_config(num_elements, x.dtype)
    grid_size = min(triton.cdiv(num_elements, block_size), MAX_GRID)
    with torch_device_fn.device(x.device):
        arccosh_kernel[(grid_size,)](
            x,
            out,
            num_elements,
            BLOCK=block_size,
            EVEN=(num_elements % block_size == 0),
            SLAB=slab,
            num_warps=num_warps,
        )
    return out


def _out_dtype(input):
    # Match PyTorch's INT_TO_FLOAT promotion: floats keep their dtype,
    # integer/bool inputs promote to the default float dtype.
    if input.is_floating_point():
        return input.dtype
    return torch.get_default_dtype()


def arccosh(A):
    logger.debug("GEMS_ENFLAME ARCCOSH")
    x = A if A.is_contiguous() else A.contiguous()
    out = torch.empty(x.shape, dtype=_out_dtype(x), device=x.device)
    _launch(x, out)
    return out


def arccosh_out(A, out):
    logger.debug("GEMS_ENFLAME ARCCOSH_OUT")
    x = A if A.is_contiguous() else A.contiguous()
    if out.is_contiguous() and out.numel() == x.numel():
        _launch(x, out)
    else:
        tmp = torch.empty(x.shape, dtype=out.dtype, device=x.device)
        _launch(x, tmp)
        out.copy_(tmp)
    return out
